scripts.lcg_update:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(K):
        X = ((A * X) + B) % M

    return float(X)

scripts.sum_quotients:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    total = 0
    for i in range(len(A)):
        quotient = A[i] // B[i]  # Integer division (floor division)
        total += quotient

    return float(total)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    count = 0

    # Check all pairs (i, j) where i < j
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.compute_gcd:
def solve(inputs: dict) -> float:
    import math

    values = inputs['VALUES']

    # Compute GCD of all values
    result = values[0]
    for i in range(1, len(values)):
        result = math.gcd(result, values[i])

    return float(result)

